with src as (select * from order_items where quantity <= 6 and order_id in (4, 12, 21)), agg as (select case when quantity >= 8 then 'high' when quantity >= 3 then 'mid' else 'low' end quantity_bucket, round(stddev(quantity), 2) stddev_quantity, count(distinct quantity) unique_products from src group by case when quantity >= 8 then 'high' when quantity >= 3 then 'mid' else 'low' end) select quantity_bucket, stddev_quantity from agg where unique_products > 6 order by stddev_quantity
